def classify(event: dict) -> dict:
    """
    Pure deterministic rule engine for classifying events.
    No ML. Matches exact real field combinations from Razorpay test-mode data.
    """
    status = event.get('status')
    error_source = event.get('error_source')
    error_code = event.get('error_code')

    if status == 'captured':
        return {
            'category': 'no_action',
            'reroutable': False,
            'confidence': 1.0,
            'reason': 'Payment already successful'
        }

    if status == 'no_payment':
        return {
            'category': 'abandoned',
            'reroutable': True,
            'confidence': 0.95,
            'reason': 'Order created but payment never attempted (checkout drop-off)'
        }

    if status == 'failed':
        if error_source == 'gateway' and error_code == 'BAD_REQUEST_ERROR':
            return {
                'category': 'gateway_failure',
                'reroutable': True,
                'confidence': 0.9,
                'reason': 'Gateway failed to process request (e.g. mock bank Failure)'
            }

        if error_source == 'customer':
            return {
                'category': 'customer_auth_failure',
                'reroutable': False,
                'confidence': 1.0,
                'reason': '[SIMULATED - taxonomy not live] Customer authentication failed'
            }

    # Fallback for unrecognized combinations
    return {
        'category': 'unknown',
        'reroutable': False,
        'confidence': 0.0,
        'reason': 'Unrecognized event pattern'
    }

import os
import requests
from requests.auth import HTTPBasicAuth

RAZORPAY_API_BASE = "https://api.razorpay.com/v1"

def _get_auth():
    key_id = os.environ.get('RAZORPAY_KEY_ID')
    key_secret = os.environ.get('RAZORPAY_KEY_SECRET')
    if not key_id or not key_secret:
        raise ValueError("RAZORPAY_KEY_ID and RAZORPAY_KEY_SECRET environment variables must be set.")
    return HTTPBasicAuth(key_id, key_secret)

def create_payment_link(amount_paise: int, description: str, reference_id: str) -> dict:
    """
    Real API call to create a Razorpay Payment Link.
    No mocking, uses real HTTP call.
    """
    url = f"{RAZORPAY_API_BASE}/payment_links"
    payload = {
        "amount": amount_paise,
        "currency": "INR",
        "description": description,
        "reference_id": reference_id,
        "customer": {
            "name": "Recovery Customer",
            "email": "recovery@example.com"
        }
    }

    response = requests.post(url, json=payload, auth=_get_auth())

    if response.status_code >= 400:
        # In real execution, we might want to log this and continue, 
        # but for bounding and transparency, let's capture the error.
        raise RuntimeError(f"Razorpay API Error: {response.text}")

    return response.json()

def fetch_payment_link_status(payment_link_id: str) -> str:
    """
    Polls whether a sent link has actually been paid.
    Returns the status string (e.g. 'paid', 'created', 'expired', 'cancelled').
    """
    url = f"{RAZORPAY_API_BASE}/payment_links/{payment_link_id}"
    response = requests.get(url, auth=_get_auth())

    if response.status_code >= 400:
        raise RuntimeError(f"Razorpay API Error fetching status: {response.text}")

    data = response.json()
    return data.get('status', 'unknown')

from rule_engine import classify
from db import log_audit, has_prior_execution
from razorpay_client import create_payment_link

class BoundedRecoveryEngine:
    def __init__(self, max_amount_per_event=5000, total_budget=20000):
        self.max_amount_per_event = max_amount_per_event
        self.budget_remaining = total_budget
        self.consecutive_failures = 0
        self.breaker_tripped = False

    def process_event(self, event: dict) -> dict:
        event_id = event.get('payment_id') # In this batch data, payment_id is our unique event identifier
        amount = event.get('amount', 0)

        classification = classify(event)

        if not classification['reroutable']:
            log_audit(event_id, "pending_approval", {
                "reason": "Not reroutable",
                "classification": classification
            })
            return {"status": "pending_approval", "reason": "not_reroutable"}

        if has_prior_execution(event_id):
            return {"status": "skipped", "reason": "prior_execution"}

        if self.breaker_tripped:
            log_audit(event_id, "pending_approval_breaker_tripped", {
                "reason": "Circuit breaker tripped (3+ consecutive failures)",
                "classification": classification
            })
            return {"status": "pending_approval_breaker_tripped"}

        # Check eligibility for auto-execution
        if classification['confidence'] < 0.85:
            log_audit(event_id, "pending_approval", {
                "reason": f"Confidence {classification['confidence']} < 0.85",
                "classification": classification
            })
            return {"status": "pending_approval", "reason": "confidence_too_low"}

        if amount > self.max_amount_per_event:
            log_audit(event_id, "pending_approval", {
                "reason": f"Amount {amount} exceeds cap {self.max_amount_per_event}",
                "classification": classification
            })
            return {"status": "pending_approval", "reason": "amount_over_cap"}

        if amount > self.budget_remaining:
            log_audit(event_id, "pending_approval", {
                "reason": f"Amount {amount} exceeds remaining budget {self.budget_remaining}",
                "classification": classification
            })
            return {"status": "pending_approval", "reason": "budget_exhausted"}

        # Eligible for execution
        log_audit(event_id, "execution_attempted", {
            "amount": amount,
            "classification": classification
        })

        try:
            amount_paise = int(amount * 100)
            link = create_payment_link(
                amount_paise=amount_paise,
                description=f"Recovery for {event_id}",
                reference_id=event_id
            )

            # Success!
            self.budget_remaining -= amount
            self.consecutive_failures = 0 # reset on success

            log_audit(event_id, "execution_result", {
                "status": "success",
                "payment_link_id": link.get("id"),
                "short_url": link.get("short_url")
            })
            return {"status": "executed", "payment_link_id": link.get("id")}

        except Exception as e:
            self.consecutive_failures += 1
            log_audit(event_id, "execution_result", {
                "status": "failure",
                "error": str(e)
            })

            if self.consecutive_failures >= 3:
                self.breaker_tripped = True

            return {"status": "execution_failed", "error": str(e)}

